#' @title Plot cluster heatmaps
#'
#' @description
#' Visualises average chromosome arm log ratio profiles
#' for BANKSY-derived spatial clusters.
#'
#' For each clustering resolution, chromosome arm log
#' ratios are averaged across cells within each cluster
#' and displayed as a heatmap.
#'
#' @param BANKSY.obj Seurat object generated by
#' compute_spatial_clusters().
#' @param resolutions Clustering resolutions to plot.
#'
#' @returns A list of ComplexHeatmap heatmap objects,
#' with one heatmap per clustering resolution.
#'
#' @examples
#' \dontrun{
#' # Plot cluster heatmap for lambda = 0.8 and resolution = 0.1
#' plot_cluster_heatmaps(
#'   BANKSY.obj,
#'   resolutions = c(0.1))}
#'
#' @export
plot_cluster_heatmaps <- function(
    BANKSY.obj,
    resolutions = c(0.1)
) {

  heatmaps <- list()

  for (res in resolutions) {

    cluster_col <- paste0(
      "BANKSY_snn_res.",
      res
    )

    if (!cluster_col %in% colnames(BANKSY.obj@meta.data)) {

      stop(
        paste(
          "Cluster column not found:",
          cluster_col
        )
      )

    }

    Seurat::Idents(BANKSY.obj) <- cluster_col

    arm_means <- Seurat::AverageExpression(
      BANKSY.obj,
      assays = "arms",
      slot = "scale.data",
      return.seurat = FALSE
    )$arms

    # chromosome arm ordering
    arm_order <- tibble::tibble(
      chr_arm = rownames(arm_means)
    ) %>%
      dplyr::mutate(
        chrom = sub("-[pq]$", "", chr_arm),
        arm = sub("^.*-", "", chr_arm),
        chrom_num = dplyr::case_when(
          chrom == "chrX" ~ 23,
          chrom == "chrY" ~ 24,
          TRUE ~ suppressWarnings(
            as.numeric(sub("chr", "", chrom))
          )
        ),
        arm = factor(
          arm,
          levels = c("p", "q")
        )
      ) %>%
      dplyr::arrange(
        chrom_num,
        arm
      ) %>%
      dplyr::pull(chr_arm)

    arm_means <- arm_means[
      arm_order,
      ,
      drop = FALSE
    ]

    colnames(arm_means) <- gsub(
      "^g",
      "C",
      colnames(arm_means)
    )

    heatmaps[[paste0("res_", res)]] <-
      ComplexHeatmap::Heatmap(
        t(as.matrix(arm_means)),
        name = "logratio",
        cluster_columns = FALSE,
        column_names_rot = 60
      )
  }

  return(heatmaps)
}
